def gen(rng):
    letters = 'abcdefghijklmnopqrstuvwxyz'
    def fmt(words, suffix):
        return str(len(words)) + '\n' + ' '.join(words) + '\n' + suffix
    def word(lo, hi, vowel=None):
        w = ''.join(rng.choice(letters) for _ in range(rng.randint(lo, hi)))
        if vowel is True:
            w = rng.choice('aeiou') + w[1:]
        elif vowel is False:
            w = rng.choice('bcdfghjklmnpqrstvwxyz') + w[1:]
        return w
    tests = [fmt(['apple', 'pie'], 'xy'), fmt(['orange', 'is', 'ripe'], 'q'), fmt(['a'], 'bc'), fmt(['b'], 'z'),
             fmt(['u', 'e', 'o'], 'a'), fmt(['zebra', 'zoo'], 'zz')]
    for w in (1, 2, 3, 4, 5, 6, 8):
        for _ in range(2):
            ws = [word(1, 6, rng.choice([True, False, None])) for _ in range(w)]
            tests.append(fmt(ws, word(1, 4)))
    tests.append(fmt([word(50, 50, True) for _ in range(1000)], word(20, 20)))
    tests.append(fmt([word(1, 50) for _ in range(1000)], word(1, 20)))
    tests.append(fmt([word(50, 50, False) for _ in range(1000)], word(20, 20)))
    tests.append(fmt([word(1, 1, True) for _ in range(1000)], 'a'))
    return tests

